const state={auth:JSON.parse(localStorage.getItem('learningNavAuth')||'null'),role:localStorage.getItem('learningNavRole')||'student',view:'home',appointments:JSON.parse(localStorage.getItem('learningNavAppointments')||'null')||[{id:'a1',professor:'陳怡君 教授',initials:'陳',topic:'專題方向討論',date:'2026-11-21',time:'14:00 - 14:30',status:'confirmed'}],slots:[{id:'s1',date:'11/21（六）',time:'14:00 - 14:30',type:'專題方向討論',status:'booked',student:'林同學'},{id:'s2',date:'11/21（六）',time:'15:00 - 15:30',type:'專輔預約',status:'open'},{id:'s3',date:'11/24（二）',time:'10:00 - 10:30',type:'研究方向諮詢',status:'open'},{id:'s4',date:'11/24（二）',time:'11:00 - 11:30',type:'專輔預約',status:'paused'}],professors:[{id:'p1',name:'陳怡君',initials:'陳',dept:'電子工程學系｜副教授',tags:['嵌入式系統','IoT','智慧醫療'],research:'專注於邊緣運算與感測器應用，適合想做軟硬體整合的同學。',available:true,slots:['11/21（六） 15:00','11/24（二） 10:00']},{id:'p2',name:'王志豪',initials:'王',dept:'資訊工程學系｜教授',tags:['人工智慧','資料科學','教育科技'],research:'以 AI 協助學習分析與校園服務，歡迎討論資料與產品想法。',available:true,slots:['11/22（日） 13:30','11/25（三） 16:00']},{id:'p3',name:'林佩珊',initials:'林',dept:'電子工程學系｜助理教授',tags:['機器人','控制系統','電腦視覺'],research:'研究人機協作與機器人控制，適合對實體互動或影像辨識有興趣的同學。',available:false,slots:[]},{id:'p4',name:'張凱文',initials:'張',dept:'資訊工程學系｜副教授',tags:['網路安全','系統軟體','雲端'],research:'從系統與安全角度打造可靠的校園服務，提供專題架構諮詢。',available:true,slots:['11/26（四） 14:00']},{id:'p5',name:'黃思妤',initials:'黃',dept:'電子工程學系｜教授',tags:['生醫訊號','AI','訊號處理'],research:'將訊號處理與 AI 結合應用於健康與學習場景。',available:true,slots:['11/27（五） 09:30']},{id:'p6',name:'周明哲',initials:'周',dept:'資訊工程學系｜助理教授',tags:['軟體工程','人機互動','UX'],research:'關注使用者體驗與軟體品質，適合需要打磨產品流程的團隊。',available:true,slots:['11/25（三） 10:30']}],courses:[{code:'CS101',name:'程式設計（一）',credit:3,status:'done',term:'大一上'},{code:'EE204',name:'電子學',credit:3,status:'done',term:'大二上'},{code:'CS220',name:'資料結構',credit:3,status:'current',term:'大二下'},{code:'CS310',name:'作業系統',credit:3,status:'todo',term:'大三上'},{code:'CS330',name:'軟體工程',credit:3,status:'todo',term:'大三上'},{code:'CS402',name:'畢業專題',credit:2,status:'todo',term:'大四上'}]};
