const app=document.getElementById('app'),toastEl=document.getElementById('toast'),modal=document.getElementById('modal'),backdrop=document.getElementById('modalBackdrop');let toastTimer;
function save(){localStorage.setItem('learningNavAppointments',JSON.stringify(state.appointments));localStorage.setItem('learningNavRole',state.role);if(state.auth)localStorage.setItem('learningNavAuth',JSON.stringify(state.auth));localStorage.setItem('learningNavTutorAvailability',JSON.stringify(state.tutorAvailability))}
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(m){toastEl.querySelector('p').textContent=m;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600)}
function initialsAvatar(i,cls='person-avatar'){return `<div class="${cls}">${i}</div>`}
function setView(v){state.view=v;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
function updateHeader(){const labels={home:['總覽','我的學習空間'],appointments:['我的預約','預約與專輔紀錄'],professors:['教授探索','找到適合你的指導者'],courses:['修課地圖','掌握畢業路徑'],tutors:['專輔專區','依科目找到專輔老師'],university:['全校公開資料','系所、師資與資料來源']};document.getElementById('breadcrumbRoot').textContent=labels[state.view]?.[0]||'總覽';document.getElementById('breadcrumbCurrent').textContent=labels[state.view]?.[1]||'';const student=state.role==='student',auth=state.auth||{};document.querySelectorAll('.role-btn').forEach(b=>b.classList.toggle('active',b.dataset.role===state.role));const local=auth.email?auth.email.split('@')[0]:'';document.getElementById('topUserName').textContent=auth.email?(student?`${local} 同學`:`${local} 師長`):(student?'林同學':'陳怡君教授');document.getElementById('topUserRole').textContent=auth.email?(student?'長庚學生帳號':'長庚師長帳號'):(student?'資工系｜大三':'電子工程學系｜副教授');document.querySelector('.avatar').textContent=auth.email?local.slice(0,1).toUpperCase():(student?'林':'陳');document.getElementById('appointmentBadge').textContent=student?state.appointments.length:'3'}function render(){updateHeader();if(state.view==='university')return renderUniversity();if(state.view==='tutors')return renderTutors();if(state.role==='professor')return renderProfessor();if(state.view==='professors')return renderProfessors();if(state.view==='courses'){renderCourses();addCourseSources();return}if(state.view==='appointments')return renderAppointments();renderStudent();replaceHomeFaculty()}
function statCard(icon,label,value,sub,accent){return `<div class="stat-card" style="--accent:${accent}"><div class="stat-icon">${icon}</div><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`}
function professorCard(p){return `<article class="prof-card"><div class="prof-top">${initialsAvatar(p.initials)}<div><h3>${esc(p.name)} 教授</h3><div class="dept">${esc(p.dept)}</div></div></div><div class="tag-row">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="research">${esc(p.research)}</p><div class="prof-bottom"><span class="availability" style="color:${p.available?'var(--green)':'#9aa5b7'}">${p.available?'本週有時段':'近期無時段'}</span><button class="ghost-btn" data-prof="${p.id}">查看時段</button></div></article>`}
function renderStudent(){const ap=state.appointments[0];app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">MONDAY, NOVEMBER 16, 2026</p><h1>早安，林同學</h1><p>今天想先處理哪一件學習任務？</p></div><button class="primary-btn" data-action="explore">＋ 探索教授與時段</button></div><div class="grid stats-grid">${statCard('◷','即將到來的預約',state.appointments.length,'保持你的討論節奏','#2d5bdb')}${statCard('✓','已修學分','48 / 128','本學期進度穩定','#11a77e')}${statCard('!','待完成必修','3','建議安排大三上','#ffd529')}${statCard('✦','推薦教授','4','依你的興趣推薦','#bd31d8')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>下一個專輔</h2><p>預約狀態與行動提醒集中在這裡</p></div><button class="link-btn" data-view="appointments">查看全部 →</button></div>${ap?`<div class="appointment-highlight"><span class="label">${formatDate(ap.date)}｜${ap.time}</span><div class="date">${esc(ap.topic)}</div><div class="desc">${esc(ap.professor)}　·　線上／管理大樓未來教室</div><div class="appointment-actions"><button class="view" data-action="view-appointment">查看預約</button><button class="cancel" data-action="cancel-appointment">取消預約</button></div></div>`:`<div class="empty-state">目前沒有預約，去探索一位教授吧。</div>`}</section><section class="panel"><div class="panel-head"><div><h2>修課進度</h2><p>大三上必修地圖</p></div><button class="link-btn" data-view="courses">查看地圖 →</button></div><div class="progress-wrap"><div class="progress-line"><i style="width:38%"></i></div><div class="progress-meta"><span>已完成 48 學分</span><strong>38%</strong></div></div><div class="mini-list" style="margin-top:16px">${state.courses.filter(c=>c.status!=='done').slice(0,3).map(c=>`<div class="course-row"><i class="course-status ${c.status}"></i><div class="course-info"><strong>${c.name}</strong><small>${c.term}｜${c.credit} 學分</small></div><span class="course-credit">${c.status==='current'?'進行中':'未修'}</span></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h2>依你的興趣推薦</h2><p>根據「軟體 × 電子 × 校園應用」推薦</p></div><button class="link-btn" data-view="professors">看更多 →</button></div><div class="grid prof-grid">${state.professors.slice(0,3).map(professorCard).join('')}</div></section>`;bind()}
function renderProfessors(){app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">EXPLORE MENTORS</p><h1>找到適合你的教授</h1><p>用專長、研究主題與可預約時段，縮短尋找與溝通的距離。</p></div></div><div class="filter-row"><input class="search-input" id="profSearch" placeholder="搜尋教授、研究主題或關鍵字"/><select class="select-input" id="deptFilter"><option value="all">全部系所</option><option>資訊工程學系</option><option>電子工程學系</option></select><select class="select-input" id="availabilityFilter"><option value="all">所有狀態</option><option value="available">本週有時段</option></select></div><div class="grid prof-grid" id="profGrid">${state.professors.map(professorCard).join('')}</div>`;bind();document.getElementById('profSearch').addEventListener('input',filterProfessors);document.getElementById('deptFilter').addEventListener('change',filterProfessors);document.getElementById('availabilityFilter').addEventListener('change',filterProfessors)}
function filterProfessors(){const q=document.getElementById('profSearch').value.toLowerCase(),dept=document.getElementById('deptFilter').value,av=document.getElementById('availabilityFilter').value;document.getElementById('profGrid').innerHTML=state.professors.filter(p=>(!q||[p.name,p.dept,p.research,...p.tags].join(' ').toLowerCase().includes(q))&&(dept==='all'||p.dept.includes(dept))&&(av==='all'||p.available)).map(professorCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合的教授，換個關鍵字試試。</div>`;bind()}
function renderAppointments(){app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">MY APPOINTMENTS</p><h1>我的預約</h1><p>預約、取消與專輔紀錄都集中在這裡。</p></div><button class="primary-btn" data-action="explore">＋ 新增預約</button></div><div class="panel"><div class="panel-head"><div><h2>即將到來</h2><p>確認時間，準時帶著問題來</p></div><span class="sub">${state.appointments.length} 筆預約</span></div>${state.appointments.length?`<div class="appointment-list">${state.appointments.map(a=>`<div class="appointment-row">${initialsAvatar(a.initials||a.professor[0])}<div class="info"><strong>${esc(a.topic)}</strong><span>${esc(a.professor)}　·　${formatDate(a.date)} ${a.time}</span></div><span class="status-confirmed">已確認</span><button class="danger-btn" data-action="cancel-appointment" data-id="${a.id}">取消</button></div>`).join('')}</div>`:`<div class="empty-state">還沒有預約，從教授探索開始吧。</div>`}</div><div class="grid two-col" style="margin-top:18px"><section class="panel"><div class="panel-head"><div><h2>專輔小提醒</h2><p>讓每次討論都更有效率</p></div></div><div class="course-row"><i class="course-status current"></i><div class="course-info"><strong>先寫下你想帶走的答案</strong><small>把問題、背景與期待結果先整理成三行。</small></div></div><div class="course-row"><i class="course-status current"></i><div class="course-info"><strong>討論後留下下一步</strong><small>完成後記錄待辦，下一次更快進入狀況。</small></div></div></section><section class="panel"><div class="panel-head"><div><h2>通知中心</h2><p>最新的預約異動</p></div></div><div class="mini-list"><div class="mini-list-item"><span class="person-avatar" style="background:#fff0fa;color:var(--purple)">✦</span><div><strong>預約提醒</strong><span>你的專題方向討論將於 11/21 開始。</span></div></div><div class="mini-list-item"><span class="person-avatar" style="background:#e9f8f7;color:var(--green)">✓</span><div><strong>資料已同步</strong><span>本學期必選修清單已更新。</span></div></div></div></section></div>`;bind()}
function renderCourses(){const done=state.courses.filter(c=>c.status==='done').length;app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">COURSE MAP</p><h1>修課地圖</h1><p>把必選修、已修學分與下一步放在同一張地圖上。</p></div><button class="secondary-btn" data-action="sync-courses">↻ 同步課程資料</button></div><div class="grid course-layout"><section class="panel"><div class="panel-head"><div><h2>資工系必修清單</h2><p>示範資料｜可替換為系所正式課程資料</p></div><span class="sub">${done}/${state.courses.length} 已完成</span></div><table class="course-table"><thead><tr><th>課程</th><th>學期</th><th>學分</th><th>狀態</th></tr></thead><tbody>${state.courses.map(c=>`<tr><td><strong>${esc(c.name)}</strong><br><small style="color:var(--muted);font-size:10px">${c.code}</small></td><td>${c.term}</td><td>${c.credit}</td><td><span class="status-pill ${c.status}">${c.status==='done'?'已修畢':c.status==='current'?'進行中':'未修'}</span></td></tr>`).join('')}</tbody></table></section><section class="panel course-summary"><h2>你的畢業路徑</h2><p>依目前修課狀態估算</p><div class="big">48<small> / 128 學分</small></div><span class="summary-label">已完成 38%</span><div class="progress-line" style="margin-top:12px;background:#ffffff2a"><i style="width:38%;background:var(--yellow)"></i></div><div class="summary-list"><div><span>已修必修</span><strong>8 門</strong></div><div><span>進行中</span><strong>1 門</strong></div><div><span>建議下學期</span><strong>2 門</strong></div></div></section></div><h2 class="section-title">建議下一步</h2><div class="grid two-col"><section class="panel"><div class="mini-list-item"><span class="person-avatar" style="background:#fff6d3;color:#9f7b00">!</span><div><strong>先安排「作業系統」專輔</strong><span>這門課是後續系統軟體課程的先修核心。</span></div><button class="link-btn" data-action="explore">找教授</button></div></section><section class="panel"><div class="mini-list-item"><span class="person-avatar" style="background:#f3e9ff;color:var(--purple)">✦</span><div><strong>把畢業專題想法記下來</strong><span>可以先從教授探索頁找感興趣的研究方向。</span></div><button class="link-btn" data-view="professors">探索</button></div></section></div>`;bind()}
function renderProfessor(){if(state.view==='professors')return renderProfessorSlots();if(state.view==='appointments')return renderProfessorAppointments();app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">PROFESSOR SPACE</p><h1>教授工作台</h1><p>即時管理可預約時段，讓學生更快找到你。</p></div><button class="primary-btn" data-action="add-slot">＋ 新增可預約時段</button></div><div class="grid stats-grid">${statCard('◷','本週可預約時段',state.slots.filter(s=>s.status==='open').length,'還有空間接住學生','#2d5bdb')}${statCard('◎','待處理預約','3','請於今天確認','#ffd529')}${statCard('✓','本月完成專輔','18','比上月多 12%','#11a77e')}</div><div class="grid two-col"><section class="panel"><div class="panel-head"><div><h2>時段管理</h2><p>學生會看到「開放」的時段</p></div><button class="link-btn" data-view="professors">查看全部 →</button></div><div class="slot-list">${state.slots.map(slotRow).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>今日預約</h2><p>快速掌握學生需求</p></div><button class="link-btn" data-view="appointments">查看全部 →</button></div><div class="appointment-list">${['林同學｜專題方向討論','陳同學｜修課規劃','吳同學｜研究方向諮詢'].map((x,i)=>`<div class="appointment-row">${initialsAvatar(['林','陳','吳'][i])}<div class="info"><strong>${x.split('｜')[0]}</strong><span>${x.split('｜')[1]}　·　${['14:00','15:30','16:30'][i]}</span></div><span class="${i===0?'status-confirmed':'status-pending'}">${i===0?'已確認':'待確認'}</span></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h2>給學生的探索資訊</h2><p>這些內容會顯示在教授卡片上</p></div><button class="ghost-btn" data-action="edit-profile">編輯資料</button></div><div class="grid two-col" style="margin:0"><div><div class="field"><label>研究關鍵字</label><input value="嵌入式系統、IoT、智慧醫療" readonly></div></div><div><div class="field"><label>專長簡介</label><textarea readonly>專注於邊緣運算與感測器應用，適合想做軟硬體整合的同學。</textarea></div></div></div></section>`;bind()}
function slotRow(s){return `<div class="slot-row"><div class="slot-time">${s.date}<br><span style="font-size:10px;color:var(--blue)">${s.time}</span></div><div class="slot-info"><strong>${s.type}</strong><span>${s.status==='booked'?`已由 ${s.student} 預約`:'學生可直接預約'}</span></div><span class="slot-state ${s.status==='paused'?'off':''}">${s.status==='open'?'開放中':s.status==='booked'?'已預約':'已暫停'}</span>${s.status!=='booked'?`<button class="slot-toggle" data-slot="${s.id}">${s.status==='open'?'暫停':'開放'}</button>`:''}</div>`}
function renderProfessorSlots(){app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">AVAILABILITY</p><h1>時段管理</h1><p>公開清楚的時間，學生就能少一封來回詢問的信。</p></div><button class="primary-btn" data-action="add-slot">＋ 新增時段</button></div><section class="panel"><div class="panel-head"><div><h2>陳怡君教授｜本週時段</h2><p>你可以隨時暫停、重新開放或新增時段。</p></div></div><div class="slot-list">${state.slots.map(slotRow).join('')}</div></section>`;bind()}
function renderProfessorAppointments(){app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">STUDENT REQUESTS</p><h1>預約管理</h1><p>查看學生的討論主題，提前準備更有品質的專輔。</p></div></div><section class="panel"><div class="panel-head"><div><h2>本週預約</h2><p>共 3 筆預約</p></div><span class="sub">最近更新：剛剛</span></div><div class="appointment-list">${['林同學','陳同學','吳同學'].map((n,i)=>`<div class="appointment-row">${initialsAvatar(n[0])}<div class="info"><strong>${n}｜${['專題方向討論','修課規劃','研究方向諮詢'][i]}</strong><span>${['11/21（六）14:00 - 14:30','11/21（六）15:30 - 16:00','11/22（日）16:30 - 17:00'][i]}</span></div><span class="${i===0?'status-confirmed':'status-pending'}">${i===0?'已確認':'待確認'}</span><button class="ghost-btn" data-action="confirm-request">${i===0?'查看':'確認'}</button></div>`).join('')}</div></section>`;bind()}
function renderCourses(){const done=state.courses.filter(c=>c.status==='done').length;const selected=state.courseYears.find(x=>x.year==='大一')||state.courseYears[0];const rows=[...selected.required.map(x=>({...x,category:'系必修'})),...selected.electives.map(x=>({...x,category:'系選修'}))];const statusFor=code=>{const current=state.courses.find(c=>c.code===code);return current?.status||'todo'};app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">COURSE MAP</p><h1>修課地圖</h1><p>查看每學年的系必修與系選修，對照自己的修課狀態規劃下一步。</p></div><button class="secondary-btn" data-action="sync-courses">↻ 同步課程資料</button></div><div class="grid course-layout"><section class="panel"><div class="panel-head"><div><h2>每學年系必選修課表</h2><p>目前為資工系示範課表，可替換為正式系所資料</p></div><select class="select-input year-select" id="courseYearSelect">${state.courseYears.map(x=>`<option value="${x.year}" ${x.year===selected.year?'selected':''}>${x.year}</option>`).join('')}</select></div><div class="course-legend"><span><i class="legend-dot required"></i>系必修</span><span><i class="legend-dot elective"></i>系選修</span><span><i class="legend-dot done"></i>已修／進行中</span></div><table class="course-table year-course-table"><thead><tr><th>課程</th><th>類別</th><th>學分</th><th>開課</th><th>我的狀態</th></tr></thead><tbody>${rows.map(x=>{const s=statusFor(x[0]);return`<tr><td><strong>${x[1]}</strong><br><small style="color:var(--muted);font-size:10px">${x[0]}</small></td><td><span class="course-category ${x.category==='系必修'?'required':'elective'}">${x.category}</span></td><td>${x[2]}</td><td>${x[3]}</td><td><span class="status-pill ${s}">${s==='done'?'已修畢':s==='current'?'進行中':'未修'}</span></td></tr>`}).join('')}</tbody></table><div class="table-footnote">課表資料可由系辦維護；學生端只需更新自己的已修紀錄，就能即時看到未修課程。</div></section><section class="panel course-summary"><h2>你的畢業路徑</h2><p>依目前修課狀態估算</p><div class="big">48<small> / 128 學分</small></div><span class="summary-label">已完成 38%</span><div class="progress-line" style="margin-top:12px;background:#ffffff2a"><i style="width:38%;background:var(--yellow)"></i></div><div class="summary-list"><div><span>已修必修</span><strong>8 門</strong></div><div><span>進行中</span><strong>1 門</strong></div><div><span>建議下學期</span><strong>2 門</strong></div></div></section></div><h2 class="section-title">建議下一步</h2><div class="grid two-col"><section class="panel"><div class="mini-list-item"><span class="person-avatar" style="background:#fff6d3;color:#9f7b00">!</span><div><strong>先安排「作業系統」專輔</strong><span>這門課是後續系統軟體課程的先修核心。</span></div><button class="link-btn" data-action="explore">找教授</button></div></section><section class="panel"><div class="mini-list-item"><span class="person-avatar" style="background:#f3e9ff;color:var(--purple)">✦</span><div><strong>把畢業專題想法記下來</strong><span>可以先從教授探索頁找感興趣的研究方向。</span></div><button class="link-btn" data-view="professors">探索</button></div></section></div>`;bind();document.getElementById('courseYearSelect').addEventListener('change',e=>{const y=state.courseYears.find(x=>x.year===e.target.value);const list=[...y.required.map(x=>({...x,category:'系必修'})),...y.electives.map(x=>({...x,category:'系選修'}))];document.querySelector('.year-course-table tbody').innerHTML=list.map(x=>{const s=statusFor(x[0]);return`<tr><td><strong>${x[1]}</strong><br><small style="color:var(--muted);font-size:10px">${x[0]}</small></td><td><span class="course-category ${x.category==='系必修'?'required':'elective'}">${x.category}</span></td><td>${x[2]}</td><td>${x[3]}</td><td><span class="status-pill ${s}">${s==='done'?'已修畢':s==='current'?'進行中':'未修'}</span></td></tr>`}).join('')})}
function publicFaculty(){return state.publicData.faculty.map((f,i)=>({id:`f:${i}`,name:f.name.split(' / ')[0],initials:(f.name.trim()[0]||'師'),dept:f.department,location:f.location||'',tags:(f.specialty||'').split(/[、,，]/).map(x=>x.trim()).filter(Boolean).slice(0,3),research:f.specialty||'官方頁面未提供專長文字',email:f.email,phone:f.phone,degree:f.degree,profileUrl:f.profileUrl,actual:true}))}
function replaceHomeFaculty(){if(!state.publicData.faculty.length)return;const grid=document.querySelector('.panel .prof-grid');if(!grid)return;grid.innerHTML=publicFaculty().slice(0,3).map(realFacultyCard).join('');bind()}
function realFacultyCard(p){return`<article class="prof-card"><div class="prof-top">${initialsAvatar(p.initials)}<div><h3>${esc(p.name)}</h3><div class="dept">${esc(p.dept)}</div></div></div><div class="tag-row">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="research">${esc(p.research)}</p><div class="prof-bottom"><span class="availability" style="color:#7a879d">由教授登入設定時段</span><button class="ghost-btn" data-prof="${p.id}">查看資料</button></div></article>`}
function renderProfessors(){const profiles=publicFaculty();const usingReal=profiles.length>0;const deptOptions=usingReal?[...new Set(profiles.map(p=>p.dept))].sort() : ['資訊工程學系','電子工程學系'];app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">OFFICIAL FACULTY DIRECTORY</p><h1>全校教授探索</h1><p>${usingReal?`已匯入長庚官方公開師資 ${profiles.length} 筆，資料會保留官方來源連結。`:'目前顯示示範師資，正在載入官方資料。'}</p></div></div><div class="data-source-banner"><span class="source-check">✓</span><div><strong>資料來源：長庚大學官方系所網站</strong><small>公開師資資料僅供查詢；可預約時間由教授登入後自行設定。</small></div><a href="https://www.cgu.edu.tw/ch/Contents?nodeId=269" target="_blank" rel="noopener">查看官方目錄 ↗</a></div><div class="filter-row"><input class="search-input" id="profSearch" placeholder="搜尋教授、系所或研究專長"/><select class="select-input" id="deptFilter"><option value="all">全部系所</option>${deptOptions.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('')}</select><select class="select-input" id="availabilityFilter"><option value="all">所有教授</option><option value="actual">有官方資料</option></select></div><div class="grid prof-grid" id="profGrid">${(usingReal?profiles:state.professors).map(usingReal?realFacultyCard:professorCard).join('')}</div>`;bind();document.getElementById('profSearch').addEventListener('input',filterPublicFaculty);document.getElementById('deptFilter').addEventListener('change',filterPublicFaculty);document.getElementById('availabilityFilter').addEventListener('change',filterPublicFaculty)}
function filterPublicFaculty(){const profiles=publicFaculty(),q=document.getElementById('profSearch').value.toLowerCase(),dept=document.getElementById('deptFilter').value;const list=profiles.filter(p=>(!q||[p.name,p.dept,p.research].join(' ').toLowerCase().includes(q))&&(dept==='all'||p.dept===dept));document.getElementById('profGrid').innerHTML=list.map(realFacultyCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合的教授，換個關鍵字試試。</div>`;bind()}
function departmentCard(d){const count=state.publicData.faculty.filter(f=>f.department===d.name).length;return`<article class="department-card"><div class="department-top"><span class="department-icon">⌘</span><div><h3>${esc(d.name)}</h3><span>${count?`已匯入 ${count} 筆公開師資`:'官方頁面未提供可自動匯入的師資清單'}</span></div></div><div class="department-links"><a href="${d.url}" target="_blank" rel="noopener">系所官方網站 ↗</a>${d.facultyUrl?`<a href="${d.facultyUrl}" target="_blank" rel="noopener">師資頁面 ↗</a>`:''}</div></article>`}
function renderUniversity(){const ds=state.publicData.departments;app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">CGU PUBLIC DATA</p><h1>全校公開資料</h1><p>以長庚大學官方網站為來源，整理系所、師資與課程查詢入口。</p></div><a class="secondary-btn" href="https://www.cgu.edu.tw/ch/Contents?nodeId=269" target="_blank" rel="noopener">官方四大學院目錄 ↗</a></div><div class="grid stats-grid public-stats">${statCard('⌘','官方系所／研究所',ds.length,'來自長庚官方系所目錄','#2d5bdb')}${statCard('◎','公開師資筆數',state.publicData.faculty.length,'含專長與官方連結','#11a77e')}${statCard('◷','教授預約時段','登入後設定','不從課表推算','#bd31d8')}${statCard('▤','學生個人課表','登入後查看','不公開學生資料','#ffd529')}</div><div class="data-source-banner"><span class="source-check">i</span><div><strong>公開資料與個人資料分開</strong><small>這裡只放官方公開的系所與師資；教授預約時間由本人維護，學生課表需登入校務系統後才可查看。</small></div></div><div class="filter-row"><input class="search-input" id="deptSearch" placeholder="搜尋系所、研究所或學程"/></div><div class="grid department-grid" id="departmentGrid">${ds.map(departmentCard).join('')}</div>`;document.getElementById('deptSearch').addEventListener('input',()=>{const q=document.getElementById('deptSearch').value.toLowerCase();document.getElementById('departmentGrid').innerHTML=ds.filter(d=>d.name.toLowerCase().includes(q)).map(departmentCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合的系所。</div>`})}
function addCourseSources(){if(document.getElementById('courseSourcePanel')||!state.publicData.departments.length)return;const s=document.createElement('section');s.id='courseSourcePanel';s.className='panel course-source-panel';s.innerHTML=`<div class="panel-head"><div><h2>全校各系課程資料入口</h2><p>課程地圖與每學年度課表以各系官方頁面為準；系所未公開結構化課表時，保留官方入口供查閱。</p></div><a class="link-btn" href="https://i.cgu.edu.tw/" target="_blank" rel="noopener">前往 iCGU ↗</a></div><div class="course-source-grid">${state.publicData.departments.map(d=>`<a class="course-source-item" href="${d.url}" target="_blank" rel="noopener"><strong>${esc(d.name)}</strong><span>官方課程／課規入口 ↗</span></a>`).join('')}</div><div class="table-footnote">教師授課課表與學生個人課表通常需要校務系統權限；網站不會抓取或公開學生個人資料，教授則可在教授端自行新增可預約時段。</div>`;app.appendChild(s)}
function openProfessorModal(id){if(!id.startsWith('f:')){const p=state.professors.find(x=>x.id===id);openModal(`<button class="modal-close" data-action="close-modal">×</button><h2>${p.name} 教授</h2><p class="modal-sub">${p.dept}｜${p.tags.join(' · ')}</p><div class="appointment-highlight" style="margin-bottom:14px"><span class="label">教授專長</span><div class="date" style="font-size:18px">${p.tags[0]} × ${p.tags[1]}</div><div class="desc">${p.research}</div></div><h3 style="font-size:13px;margin:17px 0 7px">選擇可預約時段</h3><div class="slot-options">${(p.slots.length?p.slots:['近期尚無可預約時段']).map((s,i)=>`<button class="slot-option ${i===0&&p.slots.length?'selected':''}" ${p.slots.length?'data-slot-choice="'+s+'"':''}><strong>${s}</strong><span>${p.slots.length?'30 分鐘':'—'}</span></button>`).join('')}</div><div class="field"><label>想討論的主題</label><textarea id="topicInput" placeholder="例如：專題方向、選課規劃、研究興趣..."></textarea></div><div class="modal-actions"><button class="ghost-btn" data-action="close-modal">先看看</button><button class="primary-btn" data-action="confirm-book" data-prof-id="${p.id}" ${p.slots.length?'':'disabled'}>確認預約</button></div>`);return}const p=publicFaculty()[Number(id.split(':')[1])];openModal(`<button class="modal-close" data-action="close-modal">×</button><h2>${esc(p.name)}</h2><p class="modal-sub">${esc(p.dept)}</p><div class="appointment-highlight" style="margin-bottom:14px"><span class="label">官方公開專長</span><div class="date" style="font-size:17px">${esc(p.tags.slice(0,2).join(' × ')||'未提供')}</div><div class="desc">${esc(p.research)}</div></div><div class="public-detail-list"><div><span>電子信箱</span><strong>${esc(p.email||'官方頁面未提供')}</strong></div><div><span>電話</span><strong>${esc(p.phone||'官方頁面未提供')}</strong></div></div><div class="data-source-banner compact"><span class="source-check">↗</span><div><strong>預約時間由教授本人維護</strong><small>目前尚未在平台公開可預約時段。</small></div></div><div class="modal-actions"><a class="secondary-btn" href="${p.profileUrl}" target="_blank" rel="noopener">查看官方完整資料 ↗</a><button class="ghost-btn" data-action="close-modal">關閉</button></div>`)}
const courseKeywordMap={'程式設計（一）':['程式','軟體','系統'],'程式設計（二）':['程式','軟體','系統'],'資料結構':['資料','演算法','人工智慧'],'離散數學':['演算法','理論','資料'],'計算機組織':['計算機','架構','嵌入式'],'電子學':['電子','半導體','電路'],'作業系統':['作業系統','嵌入式','系統'],'軟體工程':['軟體','人機','系統'],'網路程式設計':['網路','通訊','雲端'],'人工智慧導論':['人工智慧','AI','資料探勘','機器學習'],'畢業專題':['專題','研究','系統'],'機器人與控制':['機器人','控制','電腦視覺'],'生醫訊號':['生醫','訊號','醫學影像'],'資訊安全':['資訊安全','網路','入侵']};
function courseOptions(){return [...new Set(state.courseYears.flatMap(y=>[...y.required,...y.electives].map(x=>x[1])))].sort((a,b)=>a.localeCompare(b,'zh-Hant'))}
function courseMatches(p,course){if(course==='all')return true;const keys=courseKeywordMap[course]||[course];const text=[p.dept,p.research,...p.tags].join(' ').toLowerCase();return keys.some(k=>text.includes(k.toLowerCase()))}
function renderProfessors(){const profiles=publicFaculty(),departments=[...new Set(profiles.map(p=>p.dept))].sort((a,b)=>a.localeCompare(b,'zh-Hant')),courses=courseOptions(),specialtyCounts={};profiles.forEach(p=>p.tags.forEach(t=>specialtyCounts[t]=(specialtyCounts[t]||0)+1));const specialties=Object.entries(specialtyCounts).sort((a,b)=>b[1]-a[1]).slice(0,80).map(x=>x[0]);app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">FACULTY SEARCH ENGINE</p><h1>教授探索</h1><p>在平台內用系所、課程方向、專長與教師姓名找到適合的教授。</p></div></div><div class="data-source-banner"><span class="source-check">✓</span><div><strong>全校官方公開師資已建立搜尋索引</strong><small>目前匯入 ${profiles.length} 筆教授資料；資料來源為長庚大學官方網站，查詢不需要離開本平台。</small></div></div><div class="search-engine-panel"><div class="search-engine-title"><span>⌕</span><div><strong>搜尋條件</strong><small>可以只填一項，也可以組合多項條件縮小結果。</small></div></div><div class="filter-row search-engine-filters"><input class="search-input" id="profSearch" placeholder="搜尋教師姓名、研究關鍵字或專長"/><select class="select-input" id="deptFilter"><option value="all">所有系所</option>${departments.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('')}</select><select class="select-input" id="courseFilter"><option value="all">所有課程方向</option>${courses.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select class="select-input" id="specialtyFilter"><option value="all">所有熱門專長</option>${specialties.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div></div><div class="search-result-head"><strong id="resultCount">${profiles.length} 位教授</strong><span>點選卡片即可查看公開專長與預約狀態</span></div><div class="grid prof-grid" id="profGrid">${profiles.map(realFacultyCard).join('')}</div>`;bind();['profSearch','deptFilter','courseFilter','specialtyFilter'].forEach(id=>document.getElementById(id).addEventListener(id==='profSearch'?'input':'change',filterPublicFaculty))}
function filterPublicFaculty(){const profiles=publicFaculty(),q=document.getElementById('profSearch').value.toLowerCase(),dept=document.getElementById('deptFilter').value,course=document.getElementById('courseFilter').value,specialty=document.getElementById('specialtyFilter').value;const list=profiles.filter(p=>(!q||[p.name,p.dept,p.research,...p.tags].join(' ').toLowerCase().includes(q))&&(dept==='all'||p.dept===dept)&&courseMatches(p,course)&&(specialty==='all'||p.tags.includes(specialty)));document.getElementById('resultCount').textContent=`${list.length} 位教授`;document.getElementById('profGrid').innerHTML=list.map(realFacultyCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合條件的教授，請調整搜尋條件。</div>`;bind()}
function realFacultyCard(p){return`<article class="prof-card"><div class="prof-top">${initialsAvatar(p.initials)}<div><h3>${esc(p.name)}</h3><div class="dept">${esc(p.dept)}</div></div></div><div class="tag-row">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="research">${esc(p.research)}</p><div class="prof-bottom"><span class="availability" style="color:#7a879d">教授登入後設定時段</span><button class="ghost-btn" data-prof="${p.id}">查看資料</button></div></article>`}
function departmentCard(d){const count=state.publicData.faculty.filter(f=>f.department===d.name).length;return`<article class="department-card"><div class="department-top"><span class="department-icon">⌘</span><div><h3>${esc(d.name)}</h3><span>${count?`已匯入 ${count} 筆公開師資`:'官方頁面尚未提供可自動匯入的師資清單'}</span></div></div><div class="department-index-status">已納入教授與課程方向搜尋索引</div></article>`}
function renderUniversity(){const ds=state.publicData.departments;app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">CGU PUBLIC DATA</p><h1>全校公開資料</h1><p>官方資料已整理到平台內，學生可以直接搜尋，不需要逐一開啟系所網站。</p></div></div><div class="grid stats-grid public-stats">${statCard('⌘','官方系所／研究所',ds.length,'已建立搜尋索引','#2d5bdb')}${statCard('◎','公開師資筆數',state.publicData.faculty.length,'含公開專長資料','#11a77e')}${statCard('◷','教授預約時段','登入後設定','不從課表推算','#bd31d8')}${statCard('▤','學生個人課表','登入後查看','不公開學生資料','#ffd529')}</div><div class="data-source-banner"><span class="source-check">i</span><div><strong>公開資料與個人資料分開</strong><small>系所與師資資料可公開搜尋；教授可自行管理預約時段；學生課表只在登入後顯示。</small></div></div><div class="filter-row"><input class="search-input" id="deptSearch" placeholder="搜尋系所、研究所或學程"/></div><div class="grid department-grid" id="departmentGrid">${ds.map(departmentCard).join('')}</div>`;document.getElementById('deptSearch').addEventListener('input',()=>{const q=document.getElementById('deptSearch').value.toLowerCase();document.getElementById('departmentGrid').innerHTML=ds.filter(d=>d.name.toLowerCase().includes(q)).map(departmentCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合的系所。</div>`})}
function addCourseSources(){if(document.getElementById('courseSourcePanel')||!state.publicData.departments.length)return;const s=document.createElement('section');s.id='courseSourcePanel';s.className='panel course-source-panel';s.innerHTML=`<div class="panel-head"><div><h2>全校課程搜尋索引</h2><p>系所課程方向已納入平台搜尋；正式學年度課表會依校方公開資料更新。</p></div><span class="sub">${state.publicData.departments.length} 個系所</span></div><div class="course-source-grid">${state.publicData.departments.map(d=>`<div class="course-source-item"><strong>${esc(d.name)}</strong><span>${state.publicData.faculty.filter(f=>f.department===d.name).length} 位師資已建立索引</span></div>`).join('')}</div><div class="table-footnote">教師授課課表與學生個人課表需要校務系統權限；本平台不公開學生個資，教授則可在教授端自行新增可預約時段。</div>`;app.appendChild(s)}
function openProfessorModal(id){if(!id.startsWith('f:')){const p=state.professors.find(x=>x.id===id);openModal(`<button class="modal-close" data-action="close-modal">×</button><h2>${p.name} 教授</h2><p class="modal-sub">${p.dept}｜${p.tags.join(' · ')}</p><div class="appointment-highlight" style="margin-bottom:14px"><span class="label">教授專長</span><div class="date" style="font-size:18px">${p.tags[0]} × ${p.tags[1]}</div><div class="desc">${p.research}</div></div><h3 style="font-size:13px;margin:17px 0 7px">選擇可預約時段</h3><div class="slot-options">${(p.slots.length?p.slots:['近期尚無可預約時段']).map((s,i)=>`<button class="slot-option ${i===0&&p.slots.length?'selected':''}" ${p.slots.length?'data-slot-choice="'+s+'"':''}><strong>${s}</strong><span>${p.slots.length?'30 分鐘':'—'}</span></button>`).join('')}</div><div class="field"><label>想討論的主題</label><textarea id="topicInput" placeholder="例如：專題方向、選課規劃、研究興趣..."></textarea></div><div class="modal-actions"><button class="ghost-btn" data-action="close-modal">先看看</button><button class="primary-btn" data-action="confirm-book" data-prof-id="${p.id}" ${p.slots.length?'':'disabled'}>確認預約</button></div>`);return}const p=publicFaculty()[Number(id.split(':')[1])];openModal(`<button class="modal-close" data-action="close-modal">×</button><h2>${esc(p.name)}</h2><p class="modal-sub">${esc(p.dept)}</p><div class="appointment-highlight" style="margin-bottom:14px"><span class="label">公開專長</span><div class="date" style="font-size:17px">${esc(p.tags.slice(0,2).join(' × ')||'未提供')}</div><div class="desc">${esc(p.research)}</div></div><div class="public-detail-list"><div><span>電子信箱</span><strong>${esc(p.email||'未公開')}</strong></div><div><span>電話</span><strong>${esc(p.phone||'未公開')}</strong></div></div><div class="data-source-banner compact"><span class="source-check">⌕</span><div><strong>預約時間由教授本人維護</strong><small>目前尚未在平台公開可預約時段；教授登入後即可設定。</small></div></div><div class="modal-actions"><a class="secondary-btn" href="${p.profileUrl}" target="_blank" rel="noopener">查看官方聯絡資料 ↗</a><button class="ghost-btn" data-action="close-modal">關閉</button></div>`)}
const searchAliases={'資工':'資訊工程','資管':'資訊管理','電機':'電機工程','電子':'電子工程','企管':'工商管理','工管':'工商管理','醫工':'生物醫學工程','物治':'物理治療','職治':'職能治療','人智':'人工智慧'};
function matchesSearch(text,q){if(!q)return true;const hay=String(text).toLowerCase().replace(/\s/g,'');const query=q.toLowerCase().replace(/\s/g,'');return hay.includes(query)||(searchAliases[query]?hay.includes(searchAliases[query].toLowerCase()):false)}
function realFacultyCard(p){return`<article class="prof-card card-clickable" data-prof="${p.id}"><div class="prof-top">${initialsAvatar(p.initials)}<div><h3>${esc(p.name)}</h3><div class="dept">${esc(p.dept)}</div></div></div><div class="tag-row">${p.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="research">${esc(p.research)}</p><div class="prof-bottom"><span class="availability" style="color:#7a879d">教授登入後設定時段</span><span class="ghost-btn">查看資料</span></div></article>`}
function renderProfessors(){const profiles=publicFaculty(),departments=[...new Set(profiles.map(p=>p.dept))].sort((a,b)=>a.localeCompare(b,'zh-Hant')),courses=courseOptions(),specialtyCounts={};profiles.forEach(p=>p.tags.forEach(t=>specialtyCounts[t]=(specialtyCounts[t]||0)+1));const specialties=Object.entries(specialtyCounts).sort((a,b)=>b[1]-a[1]).slice(0,80).map(x=>x[0]),selected=state.selectedDept||'all';app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">FACULTY SEARCH ENGINE</p><h1>教授探索</h1><p>在平台內用系所、課程方向、專長與教師姓名找到適合的教授。</p></div></div><div class="data-source-banner"><span class="source-check">✓</span><div><strong>全校官方公開師資已建立搜尋索引</strong><small>目前匯入 ${profiles.length} 筆教授資料；資料來源為長庚大學官方網站，查詢不需要離開本平台。</small></div></div><div class="search-engine-panel"><div class="search-engine-title"><span>⌕</span><div><strong>搜尋條件</strong><small>可以只填一項，也可以組合多項條件縮小結果。</small></div></div><div class="filter-row search-engine-filters"><input class="search-input" id="profSearch" placeholder="搜尋教師姓名、研究關鍵字或專長"/><select class="select-input" id="deptFilter"><option value="all">所有系所</option>${departments.map(d=>`<option value="${esc(d)}" ${d===selected?'selected':''}>${esc(d)}</option>`).join('')}</select><select class="select-input" id="courseFilter"><option value="all">所有課程方向</option>${courses.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select class="select-input" id="specialtyFilter"><option value="all">所有熱門專長</option>${specialties.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div></div><div class="search-result-head"><strong id="resultCount">${profiles.length} 位教授</strong><span>點選整張教師卡即可查看公開專長與預約狀態</span></div><div class="grid prof-grid" id="profGrid">${profiles.map(realFacultyCard).join('')}</div>`;bind();['profSearch','deptFilter','courseFilter','specialtyFilter'].forEach(id=>document.getElementById(id).addEventListener(id==='profSearch'?'input':'change',filterPublicFaculty));if(selected!=='all')filterPublicFaculty()}
function filterPublicFaculty(){const profiles=publicFaculty(),q=document.getElementById('profSearch').value.toLowerCase(),dept=document.getElementById('deptFilter').value,course=document.getElementById('courseFilter').value,specialty=document.getElementById('specialtyFilter').value;const list=profiles.filter(p=>(matchesSearch([p.name,p.dept,p.research,...p.tags].join(' '),q))&&(dept==='all'||p.dept===dept)&&courseMatches(p,course)&&(specialty==='all'||p.tags.includes(specialty)));document.getElementById('resultCount').textContent=`${list.length} 位教授`;document.getElementById('profGrid').innerHTML=list.map(realFacultyCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合條件的教授，請調整搜尋條件。</div>`;bind()}
function departmentCard(d){const count=state.publicData.faculty.filter(f=>f.department===d.name).length;return`<article class="department-card card-clickable" data-department="${esc(d.name)}"><div class="department-top"><span class="department-icon">⌘</span><div><h3>${esc(d.name)}</h3><span>${count?`已匯入 ${count} 筆公開師資`:'官方頁面尚未提供可自動匯入的師資清單'}</span></div></div><div class="department-index-status">點擊查看本系所有師資 →</div></article>`}
function renderUniversity(){const ds=state.publicData.departments;app.innerHTML=`<div class="page-heading"><div><p class="eyebrow">CGU PUBLIC DATA</p><h1>全校公開資料</h1><p>選擇系所後，直接查看該系所有師資，不需要離開平台。</p></div></div><div class="grid stats-grid public-stats">${statCard('⌘','官方系所／研究所',ds.length,'已建立搜尋索引','#2d5bdb')}${statCard('◎','公開師資筆數',state.publicData.faculty.length,'含公開專長資料','#11a77e')}${statCard('◷','教授預約時段','登入後設定','不從課表推算','#bd31d8')}${statCard('▤','學生個人課表','登入後查看','不公開學生資料','#ffd529')}</div><div class="data-source-banner"><span class="source-check">i</span><div><strong>公開資料與個人資料分開</strong><small>系所與師資資料可公開搜尋；教授可自行管理預約時段；學生課表只在登入後顯示。</small></div></div><div class="filter-row"><input class="search-input" id="deptSearch" placeholder="搜尋系所，例如：資工、電子、醫學"/></div><div class="grid department-grid" id="departmentGrid">${ds.map(departmentCard).join('')}</div>`;document.getElementById('deptSearch').addEventListener('input',()=>{const q=document.getElementById('deptSearch').value;document.getElementById('departmentGrid').innerHTML=ds.filter(d=>matchesSearch(d.name,q)).map(departmentCard).join('')||`<div class="empty-state" style="grid-column:1/-1">找不到符合的系所。</div>`});document.querySelectorAll('[data-department]').forEach(card=>card.addEventListener('click',()=>{state.selectedDept=card.dataset.department;state.view='professors';render()}))}
function addCourseSources(){if(document.getElementById('courseSourcePanel')||!state.publicData.departments.length)return;const s=document.createElement('section');s.id='courseSourcePanel';s.className='panel course-source-panel';s.innerHTML=`<div class="panel-head"><div><h2>全校課程搜尋索引</h2><p>選擇系所後可查看該系師資與課程方向；正式學年度課表會依校方公開資料更新。</p></div><span class="sub">${state.publicData.departments.length} 個系所</span></div><div class="course-source-grid">${state.publicData.departments.map(d=>`<div class="course-source-item card-clickable" data-department="${esc(d.name)}"><strong>${esc(d.name)}</strong><span>${state.publicData.faculty.filter(f=>f.department===d.name).length} 位師資已建立索引</span></div>`).join('')}</div><div class="table-footnote">教師授課課表與學生個人課表需要校務系統權限；本平台不公開學生個資，教授則可在教授端自行新增可預約時段。</div>`;app.appendChild(s);s.querySelectorAll('[data-department]').forEach(card=>card.addEventListener('click',()=>{state.selectedDept=card.dataset.department;state.view='professors';render()}))}
function openProfessorModal(id){if(!id.startsWith('f:')){const p=state.professors.find(x=>x.id===id);openModal(`<button class="modal-close" data-action="close-modal">×</button><h2>${p.name} 教授</h2><p class="modal-sub">${p.dept}｜${p.tags.join(' · ')}</p><div class="appointment-highlight" style="margin-bottom:14px"><span class="label">教授專長</span><div class="date" style="font-size:18px">${p.tags[0]} × ${p.tags[1]}</div><div class="desc">${p.research}</div></div><h3 style="font-size:13px;margin:17px 0 7px">選擇可預約時段</h3><div class="slot-options">${(p.slots.length?p.slots:['近期尚無可預約時段']).map((s,i)=>`<button class="slot-option ${i===0&&p.slots.length?'selected':''}" ${p.slots.length?'data-slot-choice="'+s+'"':''}><strong>${s}</strong><span>${p.slots.length?'30 分鐘':'—'}</span></button>`).join('')}</div><div class="field"><label>想討論的主題</label><textarea id="topicInput" placeholder="例如：專題方向、選課規劃、研究興趣..."></textarea></div><div class="modal-actions"><button class="ghost-btn" data-action="close-modal">先看看</button><button class="primary-btn" data-action="confirm-book" data-prof-id="${p.id}" ${p.slots.length?'':'disabled'}>確認預約</button></div>`);return}const p=publicFaculty()[Number(id.split(':')[1])],slots=state.facultyAvailability[id]||[];openModal(`<button class="modal-close" data-action="close-modal">×</button><h2>${esc(p.name)}</h2><p class="modal-sub">${esc(p.dept)}</p><div class="appointment-highlight" style="margin-bottom:14px"><span class="label">公開專長</span><div class="date" style="font-size:17px">${esc(p.tags.slice(0,2).join(' × ')||'未提供')}</div><div class="desc">${esc(p.research)}</div></div><div class="public-detail-list"><div><span>電子信箱</span><strong>${esc(p.email||'未公開')}</strong></div><div><span>電話</span><strong>${esc(p.phone||'未公開')}</strong></div></div><h3 style="font-size:13px;margin:18px 0 7px">可預約時段</h3><div class="slot-options">${slots.length?slots.map((s,i)=>`<button class="slot-option ${i===0?'selected':''}" data-slot-choice="${esc(s)}"><strong>${esc(s)}</strong><span>30 分鐘</span></button>`).join(''):'<div class="empty-state">教授尚未公開可預約時段</div>'}</div><div class="field"><label>想討論的主題</label><textarea id="topicInput" placeholder="例如：專題方向、選課規劃、研究興趣..."></textarea></div><div class="data-source-banner compact"><span class="source-check">⌕</span><div><strong>${slots.length?'可直接提出預約':'預約時間由教授本人維護'}</strong><small>${slots.length?'選擇時段後送出預約。':'教授登入後即可設定可預約時間。'}</small></div></div><div class="modal-actions"><button class="ghost-btn" data-action="close-modal">關閉</button><button class="primary-btn" data-action="confirm-faculty-book" data-faculty-id="${id}" ${slots.length?'':'disabled'}>確認預約</button></div>`)}
